// One complete n8n run; never pass raw evidence or transcripts in a trigger.
const request=$input.first()?.json||{};
const body=request.body??request;
if(!body||typeof body!=='object'||Array.isArray(body)||body.schema!=='propria-knowledge-trigger/v1')throw Error('invalid trigger schema');
if(!['scheduled','event','manual'].includes(body.kind))throw Error('invalid trigger kind');
const scope=String(body.scope||'');
if(!(scope==='propria'||scope.startsWith('propria/'))||scope.length>120)throw Error('invalid scope');
if(Object.keys(body).some(k=>['content','records','binary','transcripts','raw'].includes(k)))throw Error('trigger must contain record references only');
const source=body.source||null;
const validSources=new Set(['memsearch','engram','cnf','docstore','propria-search','superindex','casebible','workbench','ccc']);
if(source&&!validSources.has(source))throw Error('unrecognized source');
const input={schema:body.schema,kind:body.kind,scope,source};
if(body.kind==='event'){
  if(!source||!String(body.record_ref||'').trim()||!String(body.revision||'').trim())throw Error('event identity incomplete');
  input.type=String(body.type||'');input.record_ref=String(body.record_ref).slice(0,1024);input.revision=String(body.revision).slice(0,256);
}
const stamp=typeof $execution?.id==='string'||typeof $execution?.id==='number'?$execution.id:'manual';
input.run_id='n8n-knowledge-'+String(stamp);
return [{json:input}];

// Verify source coverage, compare only same-topic records and emit candidate refs.
// Original content never moves into the review receipt; original source remains authoritative.
const payload=$input.first()?.json||{};
if(payload.schema!=='propria-knowledge-snapshot/v1'||!Array.isArray(payload.records)||!Array.isArray(payload.coverage))throw Error('snapshot schema mismatch');
if(payload.records.length>500||payload.coverage.length>30)throw Error('snapshot exceeds bounds');
const trigger=$('Validate Trigger').first().json;
const coverage=payload.coverage.map(x=>({store:String(x.store||'').slice(0,64),state:String(x.state||'unavailable').slice(0,32),reason:String(x.reason||'').slice(0,180)}));
const active=new Map(),bySubject=new Map(),fingerprints=new Set(),candidates=[];
const clean=s=>String(s||'').replace(/<!(?:--[\s\S]*?--)>/g,' ').replace(/<[^>]+>/g,' ').replace(/^\s*(?:\[(?:Tool|System|Assistant):.*|(?:User|Assistant):\s*(?:hello|thanks|ok)\s*)$/gim,'').replace(/\s+/g,' ').trim().toLowerCase();
for(const raw of payload.records){
 if(!raw||!raw.store||!raw.id||!raw.revision||!raw.scope)throw Error('snapshot record has no provenance');
 const id=String(raw.store)+':'+String(raw.id);
 if(active.has(id))throw Error('snapshot includes duplicate active identity');
 const record={key:id,store:String(raw.store),id:String(raw.id),revision:String(raw.revision),scope:String(raw.scope),subject:String(raw.subject_key||'').slice(0,240),
   claim:clean(raw.text||''),source_hash:String(raw.source_hash||''),state:String(raw.state||'active'),supersedes:Array.isArray(raw.supersedes)?raw.supersedes.map(String):[],
   expires_at:raw.expires_at||null};
 if(record.scope!==trigger.scope&&!record.scope.startsWith(trigger.scope+'/'))throw Error('out of scope record');
 if(record.state==='active'){
   active.set(id,record);
   if(record.subject){const group=bySubject.get(record.subject)||[];group.push(record);bySubject.set(record.subject,group);}
 }
}
function emit(kind,records,severity,summary) {
 const refs=[...new Set(records.map(r=>r.key))].sort();
 const signature=kind+':'+refs.join('|')+':'+records.map(r=>r.revision).sort().join('|');
 if(fingerprints.has(signature))return;fingerprints.add(signature);
 candidates.push({kind,scope:trigger.scope,source_refs:refs,source_revisions:records.map(r=>({ref:r.key,revision:r.revision})),
   severity,summary,idempotency_key:signature.slice(0,800),proposed_action:'review',automatic:false});
}
for(const r of active.values()){
 for(const predecessor of r.supersedes){
   const old=active.get(predecessor);
   if(old)emit('explicit_supersession',[old,r],'medium','A currently active record is explicitly superseded by a newer record');
 }
 if(r.expires_at){
   const expiry=Date.parse(r.expires_at);
   if(Number.isFinite(expiry)&&expiry<Date.now())emit('expired_active_record',[r],'medium','Record expiration is past but its active status remains');
 }
}
for(const group of bySubject.values()){
 if(group.length<2)continue;
 const seen=new Map();
 for(const r of group) {
   if(!r.claim)continue;
   if(seen.has(r.claim))emit('duplicate_active_claim',[seen.get(r.claim),r],'low','Two active records contain the same claim');
   else seen.set(r.claim,r);
 }
 if(seen.size>1){
   // Different text about the same subject is only a review candidate, not proof of a contradiction.
   emit('possible_topic_conflict',group.slice(0,10),
     group.some(r=>r.store==='docstore'||r.store==='engram')?'high':'medium',
     'Multiple active source assertions about the same subject differ; inspect original records');
 }
}
if(candidates.length>100)throw Error('too many candidates; narrow the scope');
return [{json:{schema:'propria-knowledge-review-proposals/v1',run_id:trigger.run_id,scope:trigger.scope,
 scanned:payload.records.length,findings:candidates.length,coverage,review_candidates:candidates}}];

// Trust only persisted PG review identities, never unverified model output.
const saved=$input.first()?.json||{};
const proposed=$('Build Review Candidates').first().json;
if(saved.schema!=='propria-knowledge-review-write/v1'||saved.run_id!==proposed.run_id||!Array.isArray(saved.review_queue))throw Error('review API did not confirm a correlated persistence receipt');
if(saved.review_queue.length>100)throw Error('review receipt too large');
const reviews=saved.review_queue.map(r=>{
 if(!r||typeof r.review_ref!=='string'||!r.review_ref||!['queued','deferred','decided'].includes(r.status)||!['low','medium','high','critical'].includes(r.severity))throw Error('review persistence unverified');
 return {review_ref:r.review_ref,status:r.status,severity:r.severity,kind:String(r.kind||'knowledge_conflict').slice(0,80),newly_created:r.newly_created===true};
});
const alerts=reviews.filter(r=>r.newly_created&&r.status==='queued'&&['high','critical'].includes(r.severity));
const incomplete=proposed.coverage.some(s=>s.state!=='queried');
const result={schema:'propria-knowledge-workflow-result/v1',run_id:proposed.run_id,
 status:incomplete?'partial':reviews.some(r=>r.status==='queued')?'review_pending':'completed',
 scanned:proposed.scanned,findings:proposed.findings,
 coverage:proposed.coverage,review_queue:reviews,alert_candidates:alerts.slice(0,20),
 alerts:[]};
if(alerts.length>20)result.status='partial';
return [{json:result}];

