// Only label an alert delivered if the SMTP node succeeded.
const previous=$('Verify Persisted Review Receipt').first().json;
const smtp=$input.first()?.json||{};
const hadError=!!smtp.error;
const result={...previous,alerts:previous.alert_candidates.map(r=>({review_ref:r.review_ref,status:hadError?'failed':'sent'}))};
delete result.alert_candidates;
if(hadError)result.status='partial';
return [{json:result}];
